# IPTVPremium: aparencia, capas maiores e ESC. Windows PowerShell 5.1 / PowerShell 7.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/androidTest/java/br/com/flaviotorres/iptvpremium/data/repository/CatalogLayoutDeviceTest.kt'; Allowed = @(); MayCreate = $true; After = 'B0D36C5904EDE43C73107BC822CB445ECA81462F0FDC680089177D3D0A77CEF9'; PayloadHash = 'B0D36C5904EDE43C73107BC822CB445ECA81462F0FDC680089177D3D0A77CEF9'; Data = '' },
    @{ Path = 'app/src/androidTest/java/br/com/flaviotorres/iptvpremium/data/repository/CatalogNavigationDeviceTest.kt'; Allowed = @('5EB56029B1768FD31D111118651AF44CB92E6DB23AB5961C83E0420442D90E1B', '876923E6F7863A7AD38C940286C0F9B8E416BEBC4E84E7418CDCBD786E3FA8C5'); MayCreate = $false; After = '96C58FA9F1752EFA2D8DC33B67791BE0F4B8FBFB86D9AAE6930C1FF68466F81D'; PayloadHash = '96C58FA9F1752EFA2D8DC33B67791BE0F4B8FBFB86D9AAE6930C1FF68466F81D'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/SettingsHubPages.kt'; Allowed = @('2CA20605ECDFAFB552F08516BC0DA5EE65D01B6FE212F7F0D11F3760DE7E8C76'); MayCreate = $false; After = '699F262B42C48863D7BE5BFFA673109C02D39A0C0B6B5F0CFDB119E73DA0FC0A'; PayloadHash = '699F262B42C48863D7BE5BFFA673109C02D39A0C0B6B5F0CFDB119E73DA0FC0A'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogEscapeBack.kt'; Allowed = @(); MayCreate = $true; After = '2817D5E023DB39F38A717E166BD9B6F3E0246FCDB7389CA2187E083BB7C33E1C'; PayloadHash = '2817D5E023DB39F38A717E166BD9B6F3E0246FCDB7389CA2187E083BB7C33E1C'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogGridGeometry.kt'; Allowed = @('817BBECC0C94D3BFAE76C47DAD5F2EDAF6ADF9185BEE8186D8B9DBCA073F6215'); MayCreate = $false; After = '84C1F08F0E390BB516F4E86D0E860156589C2274BA781B88B33983A33E78ADB7'; PayloadHash = '84C1F08F0E390BB516F4E86D0E860156589C2274BA781B88B33983A33E78ADB7'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogGridNavigation.kt'; Allowed = @('746E1CA7974F19CA20E5C7DB97BC3D5EE7D9C3F1C806B5B5DDF842E3A82232B9', '7ADD8EC05BD1CE6A2DB8B0092579933BA9950BC6EA8BD1F07F2241BBE73D86D4'); MayCreate = $false; After = 'E53CFDC0D52321F633E14F0965D37FD302AC10F88743179041C15E1E567E2AA6'; PayloadHash = 'E53CFDC0D52321F633E14F0965D37FD302AC10F88743179041C15E1E567E2AA6'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogLayoutPreview.kt'; Allowed = @(); MayCreate = $true; After = 'C62139E532E9C6373AF228E2E2BA0A335A83BA0AAF2F63EEDE6C6CE4F99B5671'; PayloadHash = 'C62139E532E9C6373AF228E2E2BA0A335A83BA0AAF2F63EEDE6C6CE4F99B5671'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogTwoRowFrame.kt'; Allowed = @(); MayCreate = $true; After = '6DF30D9DFE84AE8C91A4B3BDA8859D694DDD997E8F7D6962C1D5233204DBAB3E'; PayloadHash = '6DF30D9DFE84AE8C91A4B3BDA8859D694DDD997E8F7D6962C1D5233204DBAB3E'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/live/LiveTvScreen.kt'; Allowed = @('B150BF0C0EF928E22A551E2148CD210710BFD8658596019A3DF4C8D706F17FF3'); MayCreate = $false; After = '0F84B017631BCE79011ECA04566058752FD2C3E1EF0BDB1C5B8DF417DA744F6D'; PayloadHash = '0F84B017631BCE79011ECA04566058752FD2C3E1EF0BDB1C5B8DF417DA744F6D'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MoviesScreen.kt'; Allowed = @('FC8D7BA9E8F0C778C4A6F5FB9E090ECAB05667535D0210E9F51F0250C7DCAD84', 'AE55A8D73C0E5F169E8EFFD81061C2796EFFF253DF857544C8DB21D4801D59E8'); MayCreate = $false; After = 'D6240D5AF3EEEA09AFC6C1D1E219C71C71801147CF9F0FCA53AE03E97C105D88'; PayloadHash = 'D6240D5AF3EEEA09AFC6C1D1E219C71C71801147CF9F0FCA53AE03E97C105D88'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/series/SeriesScreen.kt'; Allowed = @('A664254F0EF3E724318D1FDFD6FBEEF11BC64DF4B0F0093CE0CC7575C8E942A3', 'B03F0353F2937EF01E1FBE4A6423133653C25913EE43EF4D3FFC858049AC9CF4'); MayCreate = $false; After = 'AFBB5FC852BAE1A78A644B4165DEE7649C1AC9A986FBE66D2F1F5C7E466C6910'; PayloadHash = 'AFBB5FC852BAE1A78A644B4165DEE7649C1AC9A986FBE66D2F1F5C7E466C6910'; Data = '' }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (pasta com app e gradlew), ou informe -Projeto.'
}
# Verifica a versao de todos os arquivos antes de escrever qualquer mudanca.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    $present = Test-Path -LiteralPath $path -PathType Leaf
    $original = $null
    if ($present) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = Get-TextHash $original
        if ($current -eq $file.After) { continue }
        if ($file.Allowed -notcontains $current) {
            throw "Arquivo com mudancas diferentes da versao enviada: $($file.Path). Nada foi alterado; suas mudancas foram preservadas."
        }
    } elseif (!$file.MayCreate) {
        throw "Arquivo necessario ausente: $($file.Path). Nada foi alterado."
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($file.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $file.PayloadHash) { throw 'Pacote com integridade invalida. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes; Original = $original; Present = $present; Hash = $file.PayloadHash }
}
if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}
$backup = Join-Path $root ('.navigation-backups/aparencia-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[IO.Directory]::CreateDirectory($backup) | Out-Null
foreach ($file in $pending) {
    if ($file.Present) {
        $copy = Join-Path $backup $file.Relative
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
        [IO.File]::Copy($file.Path, $copy, $false)
        if ((Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash -ne (Get-BytesHash $file.Original)) {
            throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
        }
    }
}
@($pending | ForEach-Object { @{ path = $_.Relative; existed = $_.Present } }) |
    ConvertTo-Json | Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding UTF8
try {
    foreach ($file in $pending) {
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path)) | Out-Null
        [IO.File]::WriteAllBytes($file.Path, $file.Bytes)
        if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne $file.Hash) { throw "Falha ao gravar $($file.Relative)." }
    }
} catch {
    foreach ($file in $pending) {
        if ($file.Present) { [IO.File]::WriteAllBytes($file.Path, $file.Original) }
        elseif (Test-Path -LiteralPath $file.Path -PathType Leaf) { [IO.File]::Delete($file.Path) }
    }
    throw
}
Write-Host 'Atualizacao aplicada: 2 fileiras de 4 ou 5 capas, cantos discretos, previa na Aparencia e ESC para voltar.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Compile e execute pelo Android Studio para validar no seu aparelho.'
